import { createTaskPanel } from './tasks.js';

const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function button(label, onClick) {
  const element = document.createElement('button');
  element.type = 'button';
  element.textContent = label;
  element.addEventListener('click', onClick);
  return element;
}

function navigate(path) {
  history.pushState(null, '', path);
  render();
}

function showError(container, error) {
  container.textContent = error.message;
  container.hidden = false;
}

let renderVersion = 0;
async function render() {
  const version = ++renderVersion;
  app.setAttribute('aria-busy', 'true');
  app.replaceChildren();
  const heading = document.createElement('h1');
  const alert = document.createElement('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.append(button('Projects', () => navigate('/')), heading, alert);
    try {
      const project = await api(`/api/projects/${match[1]}`);
      if (version !== renderVersion) return;
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      const tasks = await createTaskPanel(project.id, api);
      if (version !== renderVersion) return;
      app.append(tasks);
    } catch (error) {
      if (version !== renderVersion) return;
      heading.textContent = 'Project unavailable';
      showError(alert, error);
    }
  } else {
    heading.textContent = 'Workboard';
    document.title = 'Workboard';
    const form = document.createElement('form');
    const label = document.createElement('label');
    label.htmlFor = 'project-name';
    label.textContent = 'Project name';
    const input = document.createElement('input');
    input.id = 'project-name';
    input.name = 'name';
    input.type = 'text';
    const submit = document.createElement('button');
    submit.type = 'submit';
    submit.textContent = 'Create project';
    form.append(label, input, submit);
    const list = document.createElement('div');
    list.setAttribute('aria-label', 'Projects');
    function addProject(project) {
      const row = document.createElement('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.textContent = project.name;
      row.append(name, button('Open project', () => navigate(`/projects/${project.id}`)));
      list.append(row);
    }
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      alert.hidden = true;
      if (!input.value.trim()) {
        showError(alert, new Error('Project name is required'));
        return;
      }
      submit.disabled = true;
      try {
        const project = await api('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: input.value }),
        });
        if (version !== renderVersion) return;
        addProject(project);
        input.value = '';
        input.focus();
      } catch (error) {
        if (version === renderVersion) showError(alert, error);
      } finally {
        submit.disabled = false;
      }
    });
    app.append(heading, form, alert, list);
    // Do not allow a creation to race the initial list load.
    submit.disabled = true;
    try {
      const projects = await api('/api/projects');
      if (version !== renderVersion) return;
      projects.forEach(addProject);
    } catch (error) {
      if (version !== renderVersion) return;
      showError(alert, error);
    }
    submit.disabled = false;
  }
  app.setAttribute('aria-busy', 'false');
}

window.addEventListener('popstate', render);
render();

export async function createTaskPanel(projectId, api) {
  const path = `/api/projects/${projectId}/tasks`;
  const tasks = await api(path);
  const panel = document.createElement('section');
  panel.setAttribute('aria-label', 'Tasks');
  const form = document.createElement('form');
  const label = document.createElement('label');
  label.htmlFor = 'task-title';
  label.textContent = 'Task title';
  const input = document.createElement('input');
  input.id = 'task-title';
  input.type = 'text';
  input.name = 'title';
  const submit = document.createElement('button');
  submit.type = 'submit';
  submit.textContent = 'Create task';
  form.append(label, input, submit);

  const alert = document.createElement('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  function showError(error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }

  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'task-filter';
  filterLabel.textContent = 'Task filter';
  const filter = document.createElement('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    filter.append(option);
  }
  filter.value = 'All';
  const filterBar = document.createElement('div');
  filterBar.className = 'task-filter';
  filterBar.append(filterLabel, filter);
  const list = document.createElement('div');
  list.setAttribute('aria-label', 'Tasks');

  function renderTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      const row = document.createElement('div');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      const title = document.createElement('span');
      title.textContent = task.title;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        alert.hidden = true;
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, saved);
          renderTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error);
        } finally {
          checkbox.disabled = false;
        }
      });
      row.append(checkbox, title);
      list.append(row);
    }
  }
  filter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    if (!input.value.trim()) {
      showError(new Error('Task title is required'));
      return;
    }
    submit.disabled = true;
    try {
      const task = await api(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      });
      tasks.push(task);
      renderTasks();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(error);
    } finally {
      submit.disabled = false;
    }
  });
  panel.append(form, alert, filterBar, list);
  renderTasks();
  return panel;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { createServer } from 'node:net';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function availablePort() {
  const server = createServer();
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

test('projects and tasks validate, remain isolated, and persist across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = await availablePort();
  const base = `http://127.0.0.1:${port}`;
  let child;
  let output = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'db.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    child.stdout.on('data', (chunk) => { output += chunk; });
    child.stderr.on('data', (chunk) => { output += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      try {
        const response = await fetch(`${base}/health`);
        if (response.ok) return;
      } catch {}
      if (child.exitCode !== null) throw new Error(output);
      await new Promise((resolve) => setTimeout(resolve, 30));
    }
    throw new Error(`Server did not start: ${output}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
  }
  async function tasks(projectId, suffix = '', method = 'GET', body) {
    return fetch(`${base}/api/projects/${projectId}/tasks${suffix}`, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  }
  try {
    await start();
    const health = await fetch(`${base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    for (const name of ['', '  \n\t ']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<script>literal name</script>')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`]) {
      const response = await fetch(`${base}${path}`);
      assert.equal(response.status, 200);
      assert.match(await response.text(), /<title>Workboard<\/title>/);
    }
    assert.equal((await fetch(`${base}/api/projects/999999`)).status, 404);
    const malformed = await fetch(`${base}/api/projects`, { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
    for (const title of ['', '  \n\t ', null, 42]) {
      const response = await tasks(first.id, '', 'POST', { title });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await (await tasks(first.id)).json(), []);
    const taskResponse = await tasks(first.id, '', 'POST', { title: '  First task  ' });
    assert.equal(taskResponse.status, 201);
    const firstTask = await taskResponse.json();
    assert.equal(firstTask.title, 'First task');
    assert.equal(firstTask.completed, false);
    const secondTask = await (await tasks(first.id, '', 'POST', { title: '<b>Second task</b>' })).json();
    const otherTask = await (await tasks(second.id, '', 'POST', { title: 'Other project task' })).json();
    assert.deepEqual(await (await tasks(first.id)).json(), [firstTask, secondTask]);
    assert.deepEqual(await (await tasks(second.id)).json(), [otherTask]);
    assert.equal((await tasks(second.id, `/${firstTask.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await tasks(999999)).status, 404);
    assert.equal((await tasks(999999, '', 'POST', { title: 'No project' })).status, 404);
    assert.equal((await tasks(first.id, '/999999', 'PATCH', { completed: true })).status, 404);
    for (const completed of [1, 'true', null]) {
      assert.equal((await tasks(first.id, `/${firstTask.id}`, 'PATCH', { completed })).status, 400);
    }
    const completedResponse = await tasks(first.id, `/${firstTask.id}`, 'PATCH', { completed: true });
    assert.equal(completedResponse.status, 200);
    assert.deepEqual(await completedResponse.json(), { ...firstTask, completed: true });
    assert.deepEqual(await (await tasks(first.id, `/${firstTask.id}`, 'PATCH', { completed: false })).json(), firstTask);
    await tasks(first.id, `/${firstTask.id}`, 'PATCH', { completed: true });
    await stop();
    await start();
    assert.deepEqual(await (await tasks(first.id)).json(), [{ ...firstTask, completed: true }, secondTask]);
    assert.deepEqual(await (await tasks(second.id)).json(), [otherTask]);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { createTaskPanel } from '../public/tasks.js';

// A small DOM double exercises panel behavior without third-party dependencies.
class Element {
  constructor(tag) {
    this.tag = tag;
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this.value = '';
  }
  setAttribute(name, value) { this.attributes[name] = value; }
  append(...children) { this.children.push(...children); }
  replaceChildren(...children) { this.children = children; }
  addEventListener(name, callback) { this.listeners[name] = callback; }
  async dispatch(name) { await this.listeners[name]({ preventDefault() {} }); }
  focus() {}
}

function find(element, predicate) {
  if (predicate(element)) return element;
  for (const child of element.children) {
    const result = find(child, predicate);
    if (result) return result;
  }
}

function taskRows(element) {
  return element.children.flatMap((child) => child.dataset.testid === 'task-row' ? [child] : taskRows(child));
}

function titles(panel) {
  return taskRows(panel).map((row) => row.children[1].textContent);
}

test('task panel creates, validates, filters, toggles, and handles save failures', async () => {
  const previousDocument = globalThis.document;
  globalThis.document = { createElement: (tag) => new Element(tag) };
  const stored = [{ id: 1, title: 'Existing', completed: true }];
  let failSave = false;
  const calls = [];
  async function api(path, options) {
    calls.push({ path, options });
    if (!options) return structuredClone(stored);
    const body = JSON.parse(options.body);
    if (options.method === 'POST') {
      const task = { id: stored.length + 1, title: body.title.trim(), completed: false };
      stored.push(task);
      return { ...task };
    }
    if (failSave) throw new Error('Save failed');
    const task = stored.find((entry) => path.endsWith(`/${entry.id}`));
    task.completed = body.completed;
    return { ...task };
  }
  try {
    const panel = await createTaskPanel(7, api);
    const form = find(panel, (element) => element.tag === 'form');
    const input = find(panel, (element) => element.id === 'task-title');
    const filter = find(panel, (element) => element.id === 'task-filter');
    const alert = find(panel, (element) => element.attributes.role === 'alert');
    assert.equal(find(panel, (element) => element.htmlFor === input.id).textContent, 'Task title');
    assert.equal(find(form, (element) => element.tag === 'button').textContent, 'Create task');
    assert.equal(find(panel, (element) => element.htmlFor === filter.id).textContent, 'Task filter');
    assert.deepEqual(filter.children.map((option) => option.textContent), ['All', 'Open', 'Completed']);
    assert.equal(filter.value, 'All');
    assert.deepEqual(titles(panel), ['Existing']);
    input.value = ' \t ';
    await form.dispatch('submit');
    assert.equal(alert.hidden, false);
    assert.match(alert.textContent, /Task title is required/);
    assert.equal(calls.length, 1);
    input.value = '  New task  ';
    await form.dispatch('submit');
    assert.deepEqual(titles(panel), ['Existing', 'New task']);
    assert.equal(input.value, '');
    assert.equal(alert.hidden, true);
    filter.value = 'Open';
    await filter.dispatch('change');
    assert.deepEqual(titles(panel), ['New task']);
    let checkbox = taskRows(panel)[0].children[0];
    assert.equal(checkbox.attributes['aria-label'], 'Complete New task');
    assert.equal(checkbox.checked, false);
    checkbox.checked = true;
    await checkbox.dispatch('change');
    assert.deepEqual(titles(panel), []);
    assert.equal(stored[1].completed, true);
    filter.value = 'Completed';
    await filter.dispatch('change');
    assert.deepEqual(titles(panel), ['Existing', 'New task']);
    checkbox = taskRows(panel)[1].children[0];
    checkbox.checked = false;
    await checkbox.dispatch('change');
    assert.deepEqual(titles(panel), ['Existing']);
    filter.value = 'All';
    await filter.dispatch('change');
    assert.deepEqual(titles(panel), ['Existing', 'New task']);
    failSave = true;
    checkbox = taskRows(panel)[1].children[0];
    checkbox.checked = true;
    await checkbox.dispatch('change');
    assert.equal(checkbox.checked, false);
    assert.equal(checkbox.disabled, false);
    assert.match(alert.textContent, /Save failed/);
    assert.ok(calls.every((call) => call.path.startsWith('/api/projects/7/tasks')));
  } finally {
    if (previousDocument === undefined) delete globalThis.document;
    else globalThis.document = previousDocument;
  }
});

